    private static SaveDocument ContactBatFixture(uint randomState=1)
    {
        World world=EncounterScenarios.BluntCombatTest();world.Step();SaveDocument saved=world.Capture();saved.tick=5;saved.actors[1].x=3;saved.actors[1].y=2;saved.reactionRandomState=randomState;return saved;
