            World world=EncounterScenarios.WeaponSeekingTest();Require(CanSeekBat(world),"Visible safe bat was not eligible.");SaveDocument baseline=world.Capture();foreach(int mode in new[]{0,1,2,3,4}){SaveDocument saved=DocumentsParse(baseline);if(mode==0)saved.actors[0].stress=1;if(mode==1)saved.actors[0].turnAtTick=30;if(mode==2)saved.actors[0].reaction=HumanReaction.Flight;if(mode==3){saved.actors[0].reaction=HumanReaction.Freeze;saved.actors[0].freezeUntilTick=10;}if(mode==4)saved.actors[0].meleeWeapon=MeleeWeapon.Bat;Require(!CanSeekBat(World.Restore(saved)),"Equipment seeking overrode a survival priority.");}
